def step(grid, birth, survive):
    """Advance one generation.  Pure Python, no imports beyond stdlib."""
    new = [row[:] for row in grid]
    for y in range(H):
        row = grid[y]
        newrow = new[y]
        for x in range(W):
            n = 0
            for dy in (-1, 0, 1):
                ny = y + dy
                if not 0 <= ny < H:
                    continue
                other = grid[ny]
                for dx in (-1, 0, 1):
                    if dx == 0 and dy == 0:
                        continue
                    nx = x + dx
                    if 0 <= nx < W and other[nx]:
                        n += 1
            if row[x]:
                newrow[x] = 1 if n in survive else 0
            else:
                newrow[x] = 1 if n in birth else 0
    return new

